def transform(grid):
    """Recolor: smaller color value -> 0, larger -> smaller value.
    Reproduces all 5 demonstration/kept pairs. NOTE: the solved test
    instance (colors 5,7) used the reverse mapping (larger -> 0,
    smaller -> larger); mapping direction may vary per instance."""
    vals = sorted({v for row in grid for v in row})
    lo, hi = vals[0], vals[-1]
    return [[0 if v == lo else lo for v in row] for row in grid]


